<?php
require __DIR__.'/../app/bootstrap.php'; require_login();
$labels=['computer'=>'رایانه','printer'=>'چاپگر','display'=>'نمایشگر','scanner'=>'اسکنر'];
$where=[];$args=[];$search=trim((string)($_GET['q']??''));$type=$_GET['type']??'';$status=$_GET['status']??'';
if($search!==''){ $where[]='(a.asset_no LIKE ? OR a.hostname LIKE ? OR a.manufacturer LIKE ? OR a.model LIKE ? OR a.serial_no LIKE ? OR p.full_name LIKE ?)';for($i=0;$i<6;$i++)$args[]='%'.$search.'%'; }
if(isset($labels[$type])){$where[]='a.asset_type=?';$args[]=$type;}if(in_array($status,['active','repair','retired','lost'],true)){$where[]='a.status=?';$args[]=$status;}
$sql='SELECT a.asset_no,a.asset_type,a.device_subtype,a.hostname,a.location,a.department,a.manufacturer,a.model,a.serial_no,a.status,p.full_name personnel_name,a.updated_at FROM assets a LEFT JOIN personnel p ON p.id=a.personnel_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY a.asset_no';$st=db()->prepare($sql);$st->execute($args);$rows=$st->fetchAll();
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>گزارش تجهیزات</title><link rel="stylesheet" href="assets/app.css"></head><body><header><a class="brand" href="index.php">سامانه سخت‌افزار</a><nav><a href="index.php">داشبورد</a><a href="assets.php">تجهیزات</a><a href="report.php">گزارش</a><a href="logout.php">خروج</a></nav></header><main><div class="page-head"><div><h1>گزارش جامع تجهیزات</h1><p class="muted">فیلتر کنید و برای خروجی CSV آماده چاپ/آرشیو کنید.</p></div><a class="btn primary" href="export.php?<?=e(http_build_query($_GET))?>">خروجی CSV</a></div><section class="panel"><form class="filter" method="get"><input name="q" placeholder="جستجوی اموال، نام، برند، مدل، سریال، پرسنل..." value="<?=e($search)?>"><select name="type"><option value="">همه انواع</option><?php foreach($labels as $k=>$v):?><option value="<?=$k?>" <?=($type===$k?'selected':'')?>><?=e($v)?></option><?php endforeach;?></select><select name="status"><option value="">همه وضعیت‌ها</option><option value="active">فعال</option><option value="repair">تعمیر</option><option value="retired">اسقاط</option><option value="lost">مفقود</option></select><button class="btn">اعمال</button></form></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>اموال</th><th>نوع</th><th>نام دستگاه</th><th>برند/مدل</th><th>مسئول</th><th>مکان</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['asset_no'])?></strong></td><td><?=e($labels[$r['asset_type']]??$r['asset_type'])?></td><td><?=e($r['hostname']?:'—')?></td><td><?=e(trim(($r['manufacturer']??'').' '.($r['model']??''))?:'—')?></td><td><?=e($r['personnel_name']?:'—')?></td><td><?=e($r['location']?:'—')?></td><td><?=e($r['status'])?></td><td><a class="btn small" href="asset_view.php?asset_no=<?=e($r['asset_no'])?>">مشاهده</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="8" class="muted">موردی یافت نشد.</td></tr><?php endif;?></tbody></table></div><p class="muted">تعداد نتایج: <?=count($rows)?></p></section></main></body></html>
